   panels=''.join(f'<section class="chart-panel" id="reason-{key}" aria-labelledby="reason-title-{key}"'+(' hidden' if i else '')+f'><h4 id="reason-title-{key}">{e(title)}</h4><p>{e(text)}</p></section>' for i,(key,title,text) in enumerate(a['reason_panels']))
   introduction_html += '<div class="reason-explorer"><div class="chart-choices" role="group" aria-label="Razones para trabajar con muestras">'+choices+'</div><p class="chart-status" role="status">Mostrando Costo computacional.</p>'+panels+'<p class="data-note">Referencias: <a href="https://www.tidymodels.org/start/recipes/">evaluación predictiva, tidymodels</a> y <a href="https://www.worldbank.org/en/programs/lsms/publication/capturing-what-matters">diseño de encuestas, Banco Mundial</a>.</p></div>'
